"""Checked, local-label header compression and exact offline admission.

The only persistent objects are code and constants: every input line is
validated and evaluated against newly created control-plane state.
"""
import json
import re
import sys


MAX_LINE = 16 * 1024 * 1024
ID_RE = re.compile(r'[A-Za-z0-9_.-]{1,32}\Z', re.ASCII)
HEX_RE = re.compile(r'[0-9a-f]*\Z', re.ASCII)
KINDS_RE = re.compile(r'[KDZQT]*\Z', re.ASCII)


class InputError(Exception):
    pass


def require(condition):
    if not condition:
        raise InputError()


def object_keys(value, keys):
    require(type(value) is dict and value.keys() == keys)


def integer(value, lo, hi):
    require(type(value) is int and lo <= value <= hi)
    return value


def identifier(value):
    require(type(value) is str and ID_RE.fullmatch(value) is not None)
    return value


def hex_bytes(value, lo, hi):
    require(type(value) is str)
    size = len(value)
    require(2 * lo <= size <= 2 * hi and size % 2 == 0)
    require(HEX_RE.fullmatch(value) is not None)
    return bytes.fromhex(value)


def unique_object(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise InputError()
        obj[key] = value
    return obj


def bad_number(value):
    # No field of either schema admits fractional or non-finite numbers.
    raise InputError()


class Flow:
    __slots__ = ('id', 'path', 'template', 'ks', 'ds', 'zs', 'q', 't',
                 'labels', 'label_at')

    def __init__(self, value, capacities, replay):
        keys = {'id', 'path', 'template', 'kinds'}
        if replay:
            keys.add('labels')
        object_keys(value, keys)
        self.id = identifier(value['id'])
        path = value['path']
        require(type(path) is list and 2 <= len(path) <= 9)
        for node in path:
            identifier(node)
            require(node in capacities)
        require(len(set(path)) == len(path))
        self.path = tuple(path)
        self.template = hex_bytes(value['template'], 8, 256)
        kinds = value['kinds']
        require(type(kinds) is str and len(kinds) == len(self.template))
        require(KINDS_RE.fullmatch(kinds) is not None)
        require(kinds.count('Q') == 1 and kinds.count('T') == 1)
        require(kinds.count('K') >= 1 and 4 + kinds.count('D') < len(kinds))
        self.ks = tuple(i for i, k in enumerate(kinds) if k == 'K')
        self.ds = tuple(i for i, k in enumerate(kinds) if k == 'D')
        self.zs = tuple(i for i, k in enumerate(kinds) if k == 'Z')
        self.q = kinds.index('Q')
        self.t = kinds.index('T')
        if replay:
            labels = value['labels']
            require(type(labels) is list and len(labels) == len(path))
            for label in labels:
                integer(label, 16, 1048575)
            self.labels = tuple(labels)
            self.label_at = dict(zip(path, labels))
        else:
            self.labels = ()
            self.label_at = {}

    def matches(self, header):
        template = self.template
        return all(header[i] == template[i] for i in self.ks)


def validate(request):
    require(type(request) is dict)
    mode = request.get('mode')
    require(type(mode) is str and mode in ('replay', 'plan'))
    replay = mode == 'replay'
    keys = {'mode', 'capacities', 'flows'}
    keys.update({'events'} if replay else {'warmup', 'pinned', 'offers'})
    object_keys(request, keys)

    capacities = request['capacities']
    require(type(capacities) is dict and 1 <= len(capacities) <= 64)
    for node, capacity in capacities.items():
        identifier(node)
        integer(capacity, 0, 512)

    definitions = request['flows']
    require(type(definitions) is list and len(definitions) <= (512 if replay else 22))
    flows = {}
    for definition in definitions:
        flow = Flow(definition, capacities, replay)
        require(flow.id not in flows)
        flows[flow.id] = flow

    if replay:
        events = request['events']
        require(type(events) is list and len(events) <= 20000)
        checked = []
        packet_bytes = 0
        event_keys = {
            'put': {'op', 'flow', 'node'},
            'enable': {'op', 'flow'},
            'disable': {'op', 'flow'},
            'reset': {'op'},
            'packet': {'op', 'flow', 'header', 'payload'},
        }
        for event in events:
            require(type(event) is dict)
            op = event.get('op')
            require(type(op) is str and op in event_keys)
            object_keys(event, event_keys[op])
            if op == 'reset':
                checked.append((op,))
                continue
            fid = identifier(event['flow'])
            require(fid in flows)
            flow = flows[fid]
            if op == 'put':
                node = identifier(event['node'])
                require(node in flow.label_at)
                checked.append((op, flow, node))
            elif op == 'packet':
                h = len(flow.template)
                header = hex_bytes(event['header'], h, h)
                payload = hex_bytes(event['payload'], 0, 2048)
                packet_bytes += len(header) + len(payload)
                require(packet_bytes <= 2 * 1024 * 1024)
                checked.append((op, flow, header, payload))
            else:
                checked.append((op, flow))
        return mode, capacities, flows, checked

    warmup = integer(request['warmup'], 0, 1000000000)
    pinned_list = request['pinned']
    require(type(pinned_list) is list)
    pinned = set()
    for fid in pinned_list:
        identifier(fid)
        require(fid in flows and fid not in pinned)
        pinned.add(fid)
    offers = request['offers']
    require(type(offers) is dict and offers.keys() == flows.keys())
    header_bytes = 0
    benefits = {}
    for fid, flow in flows.items():
        runs = offers[fid]
        require(type(runs) is list and len(runs) <= 256)
        h = len(flow.template)
        switches = len(flow.path) - 1
        remaining_warmup = warmup
        total = 0
        eligible = 0
        for run in runs:
            object_keys(run, {'header', 'count'})
            header = hex_bytes(run['header'], h, h)
            header_bytes += h
            require(header_bytes <= 65536)
            count = integer(run['count'], 1, 1000000000)
            total += count
            require(total <= 1000000000)
            skipped = min(remaining_warmup, count)
            remaining_warmup -= skipped
            if (count > skipped and flow.matches(header)
                    and header[flow.q] <= 7 and header[flow.t] > switches):
                eligible += count - skipped
        benefits[fid] = eligible * (h - 4 - len(flow.ds)) * len(flow.path)
    return mode, capacities, flows, (pinned, benefits)


def packet_result(flow, header, payload, enabled):
    if not enabled:
        mode, reason = 'ip', 'disabled'
    elif not flow.matches(header):
        mode, reason = 'ip', 'mismatch'
    elif header[flow.q] > 7:
        mode, reason = 'ip', 'qos'
    else:
        mode, reason = 'mpls', 'compressed'

    ttl = header[flow.t]
    n = len(flow.path)
    links = min(ttl, n)
    wire = []
    delivered = None
    if mode == 'ip':
        current = bytearray(header)
        for i in range(links):
            current[flow.t] = ttl - i
            wire.append((current + payload).hex())
        if links == n:
            delivered = wire[-1]
        byte_hops = links * (len(header) + len(payload))
    else:
        residue = bytes(header[i] for i in flow.ds)
        tail = (residue + payload).hex()
        tc_s = (header[flow.q] << 9) | 256
        for i in range(links):
            word = (flow.labels[i] << 12) | tc_s | (ttl - i)
            wire.append(word.to_bytes(4, 'big').hex() + tail)
        if links == n:
            restored = bytearray(flow.template)
            for i, byte in zip(flow.ds, residue):
                restored[i] = byte
            for i in flow.zs:
                restored[i] = 0
            restored[flow.q] = header[flow.q]
            restored[flow.t] = ttl - (n - 1)
            delivered = (restored + payload).hex()
        byte_hops = links * (4 + len(residue) + len(payload))
    return {'mode': mode, 'reason': reason, 'wire': wire,
            'delivered': delivered, 'byte_hops': byte_hops}


def replay(capacities, flows, events):
    tables = {node: {} for node in capacities}
    active = set()
    results = []
    for event in events:
        op = event[0]
        if op == 'reset':
            active.clear()
            results.append({'status': 'ok'})
            continue
        flow = event[1]
        fid = flow.id
        if op == 'packet':
            results.append(packet_result(flow, event[2], event[3], fid in active))
            continue
        if op == 'put':
            node = event[2]
            label = flow.label_at[node]
            table = tables[node]
            previous = table.get(label)
            if previous == fid:
                status = 'ok'
            elif previous in active:
                # Readiness and this guard preserve the invariant that every
                # active flow owns all its declared (node, local label) pairs.
                status = 'busy'
            elif previous is None and len(table) >= capacities[node]:
                status = 'full'
            else:
                table[label] = fid
                status = 'ok'
        elif op == 'enable':
            if all(tables[node].get(label) == fid
                   for node, label in zip(flow.path, flow.labels)):
                active.add(fid)
                status = 'ok'
            else:
                status = 'unready'
        else:  # disable is a synchronous drain barrier, not a table deletion.
            active.discard(fid)
            status = 'ok'
        results.append({'status': status})
    entries = [{'node': node, 'label': label, 'flow': table[label]}
               for node, table in sorted(tables.items())
               for label in sorted(table)]
    return {'results': results, 'active': sorted(active), 'tables': entries}


def plan(capacities, flows, pinned, benefits):
    free = capacities.copy()
    for fid in pinned:
        for node in flows[fid].path:
            free[node] -= 1
    if any(capacity < 0 for capacity in free.values()):
        return {'infeasible': True}

    # Optional zero-benefit flows can never satisfy the secondary objective.
    # A flow touching a saturated pinned node cannot be admitted at all.
    items = [flow for fid, flow in flows.items()
             if fid not in pinned and benefits[fid] > 0
             and all(free[node] > 0 for node in flow.path)]
    items.sort(key=lambda flow: (-benefits[flow.id], flow.id))
    m = len(items)

    # A node constrains just a subset of the optional variables. Merge equal
    # constraints, and omit nodes that would fit even if all were selected.
    node_masks = {node: 0 for node in capacities}
    for i, flow in enumerate(items):
        for node in flow.path:
            node_masks[node] |= 1 << i
    constraints = {}
    for node, mask in node_masks.items():
        cap = free[node]
        if mask.bit_count() > cap:
            constraints[mask] = min(constraints.get(mask, cap), cap)

    if not constraints:
        chosen = set(pinned)
        chosen.update(flow.id for flow in items)
        return {'selected': sorted(chosen),
                'saved': sum(benefits[fid] for fid in chosen)}

    # If A is contained in B and bound(B) <= bound(A), B implies A.
    necessary = [(mask, cap) for mask, cap in constraints.items()
                 if not any(mask != other and mask & other == mask and bound <= cap
                            for other, bound in constraints.items())]

    # Pack counts for all remaining capacity constraints into six-bit lanes.
    # There are at most 22 variables, hence counts never carry between lanes.
    # Adding 31-cap sets a lane's bit 5 exactly when its capacity is exceeded.
    # This checks all nodes using two arbitrary-precision integer operations.
    codes = [0] * m
    bias = 0
    guards = 0
    for lane, (mask, cap) in enumerate(necessary):
        shift = 6 * lane
        bias |= (31 - cap) << shift
        guards |= 32 << shift
        for i in range(m):
            if mask & (1 << i):
                codes[i] |= 1 << shift

    # Encode both optimization criteria in a single integer. The factor is
    # larger than any possible difference in optional admission counts.
    weights = [benefits[flow.id] * (m + 1) - 1 for flow in items]
    suffix_weights = [0] * (m + 1)
    suffix_codes = [0] * (m + 1)
    for i in range(m - 1, -1, -1):
        suffix_weights[i] = suffix_weights[i + 1] + weights[i]
        suffix_codes[i] = suffix_codes[i + 1] + codes[i]
    all_bits = (1 << m) - 1
    suffix_bits = [all_bits ^ ((1 << i) - 1) for i in range(m + 1)]
    bits = [1 << i for i in range(m)]

    # A feasible greedy incumbent tightens bounds before the exact search.
    best_score = 0
    best_mask = 0
    load = 0
    for i in range(m):
        new_load = load + codes[i]
        if not (new_load + bias) & guards:
            load = new_load
            best_score += weights[i]
            best_mask |= bits[i]

    def search(i, load, score, mask):
        nonlocal best_score, best_mask
        upper = score + suffix_weights[i]
        if upper <= best_score:
            return
        if not (load + suffix_codes[i] + bias) & guards:
            # Every remaining weight is positive. When they all fit, this
            # upper bound is attainable without exploring its subsets.
            best_score = upper
            best_mask = mask | suffix_bits[i]
            return
        new_load = load + codes[i]
        if not (new_load + bias) & guards:
            search(i + 1, new_load, score + weights[i], mask | bits[i])
        if codes[i]:
            search(i + 1, load, score, mask)
        # An unconstrained positive variable must be included, so its exclude
        # branch is dominated. At i == m the all-fit case above always applies.

    search(0, 0, 0, 0)
    chosen = set(pinned)
    chosen.update(flow.id for i, flow in enumerate(items) if best_mask & bits[i])
    return {'selected': sorted(chosen),
            'saved': sum(benefits[fid] for fid in chosen)}


def respond(request):
    mode, capacities, flows, data = validate(request)
    if mode == 'replay':
        return replay(capacities, flows, data)
    return plan(capacities, flows, *data)


def main():
    source = sys.stdin.buffer
    while True:
        raw = source.readline(MAX_LINE + 1)
        if not raw:
            break
        if len(raw) > MAX_LINE:
            # Drain this physical line only, so a malformed oversized request
            # cannot turn into extra requests or poison subsequent lines.
            while not raw.endswith(b'\n'):
                raw = source.readline(MAX_LINE + 1)
                if not raw:
                    break
            response = {'error': 'input'}
        else:
            try:
                request = json.loads(raw.decode('utf-8'),
                                     object_pairs_hook=unique_object,
                                     parse_float=bad_number,
                                     parse_constant=bad_number)
                response = respond(request)
            except (InputError, ValueError, TypeError, RecursionError, OverflowError):
                response = {'error': 'input'}
        sys.stdout.write(json.dumps(response, separators=(',', ':')) + '\n')
        sys.stdout.flush()


if __name__ == '__main__':
    main()
